23: (()=>{'use strict';
24: const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');const W=800,H=490,COLS=16,ROWS=10,CW=W/COLS,CH=H/ROWS;
25: const routes=[[[0,2],[2,2],[2,6],[5,6],[5,3],[8,3],[8,7],[11,7],[11,4],[14,4],[14,8],[16,8]]];
26: const themes=[{name:'ORIGIN',zone:'THE VERDANT RIFT',sub:'SECTOR 01 · OUTER FRONTIER',sky:'#102721',ground:'#132b27',grid:'#2c5948',path:'#88794e',edge:'#c5a873',accent:'#71f0c1',note:'Unaltered frontier. The rift is quiet—for now.'},{name:'EMBER',zone:'THE ASHEN CONTINUUM',sub:'SECTOR 02 · COLLAPSED TIMELINE',sky:'#2d1d1b',ground:'#34211d',grid:'#6a3931',path:'#9b6949',edge:'#e19866',accent:'#ff9c6e',note:'A scorched future. Alien armor adapts to the heat.'},{name:'FROST',zone:'THE CRYSTAL PARADOX',sub:'SECTOR 03 · GLACIAL FUTURE',sky:'#14242f',ground:'#1a3039',grid:'#345969',path:'#718b91',edge:'#b1d5d9',accent:'#86e3ff',note:'Time has frozen over. Hostiles arrive in denser packs.'},{name:'VOID',zone:'THE NULL EXPANSE',sub:'SECTOR 04 · REALITY COLLAPSE',sky:'#20172e',ground:'#251b32',grid:'#503a67',path:'#78608d',edge:'#c0a3de',accent:'#d6a5ff',note:'Reality frays at the edges. Nothing returns unchanged.'}];
27: const specs={pulse:{name:'Pulse Node',cost:70,range:105,damage:12,rate:.52,color:'#71f0c1',glyph:'⌁',desc:'Rapid · balanced'},cannon:{name:'Nova Cannon',cost:115,range:125,damage:35,rate:1.35,color:'#ffc878',glyph:'✹',desc:'Heavy · splash'},cryo:{name:'Cryo Spire',cost:90,range:98,damage:7,rate:.8,color:'#77cfff',glyph:'❄',desc:'Slow · control'}};
28: const pathPts=routes[0].map(p=>({x:p[0]*CW,y:p[1]*CH}));let money=240,lives=20,wave=0,active=false,spawnLeft=0,spawnTimer=0,spawnGap=.8,speed=1,selectedType=null,selectedTower=null,hover=null,gameOver=false,frame=0,last=0,toastTimer=0,transition=false;
29: let towers=[],enemies=[],shots=[],particles=[],grid=[];for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++)grid.push({x,y});
30: const $=id=>document.getElementById(id);const theme=()=>themes[Math.floor(Math.max(0,wave-1)/3)%themes.length];
31: function routeDistance(x,y){let best=1e9;for(let i=0;i<pathPts.length-1;i++){let a=pathPts[i],b=pathPts[i+1],dx=b.x-a.x,dy=b.y-a.y,t=Math.max(0,Math.min(1,((x-a.x)*dx+(y-a.y)*dy)/(dx*dx+dy*dy)));best=Math.min(best,Math.hypot(x-(a.x+t*dx),y-(a.y+t*dy)));}return best}
32: function onPath(x,y){return routeDistance(x*CW+CW/2,y*CH+CH/2)<34}
33: function updateUI(){ $('money').textContent=money;$('lives').textContent=lives;$('wave').textContent=wave;$('hostiles').textContent=enemies.length+spawnLeft;let t=theme();$('timeline').textContent=`${String(Math.floor(Math.max(0,wave-1)/3)+1).padStart(2,'0')} · ${t.name}`;$('zoneTitle').textContent=t.zone;$('zoneSub').textContent=t.sub;$('timelineNote').innerHTML=`<b>TIMELINE ${String(Math.floor(Math.max(0,wave-1)/3)+1).padStart(2,'0')} · ${t.name}</b><br>${t.note}`;document.documentElement.style.setProperty('--mint',t.accent);$('waveButton').disabled=active||gameOver;$('waveButton').textContent=active?'◌  Wave in progress':`▶  Deploy wave ${wave+1}`;$('waveState').textContent=active?`WAVE ${wave} · ${spawnLeft+enemies.length} HOSTILES`:(gameOver?'CORE BREACHED':'AWAITING DEPLOYMENT');$('waveHint').textContent=active?'Defend the core from incoming hostiles':'Enemies grow stronger each wave';document.querySelectorAll('.tower-card').forEach(b=>b.classList.toggle('selected',b.dataset.type===selectedType));refreshSelection()}
34: function refreshSelection(){let actions=$('actions');if(selectedTower){let t=selectedTower,s=specs[t.type],upCost=upgradeCost(t);$('selectionTitle').textContent=s.name;$('selectionLevel').textContent=`LV ${t.level}`;$('selectionText').textContent=`DMG ${Math.round(s.damage*(1+(t.level-1)*.52))} · RANGE ${Math.round(s.range*(1+(t.level-1)*.09))} · ${s.desc}`;$('upgradeBtn').textContent=`⬆ Upgrade · ◈ ${upCost}`;$('upgradeBtn').disabled=t.level>=5||money<upCost;$('sellBtn').textContent=`Sell · ◈ ${Math.floor(s.cost*.6+(t.level-1)*upCost*.45)}`;actions.hidden=false}else{actions.hidden=true;if(selectedType){let s=specs[selectedType];$('selectionTitle').textContent=`${s.name} selected`;$('selectionLevel').textContent=`◈ ${s.cost}`;$('selectionText').textContent=`${s.desc}. Click an open tile to deploy this defense system.`}else{$('selectionTitle').textContent='No unit selected';$('selectionLevel').textContent='';$('selectionText').textContent='Choose a defense system above, then place it on an open tile beside the alien route.'}}}
